// Recuperer les textes du profil et du guide
const profilText = $('Extraire texte profil').first().json.profilBusiness || '';
const guideText = $('Extraire texte guide').first().json.guideEditorial || '';

// Recuperer le resultat Perplexity (1 seul appel veille 96h)
const perplexityResult = $('Perplexity Veille 96h').first().json;

const resultats_veille = {
  contenu: perplexityResult.choices?.[0]?.message?.content || '',
  citations: perplexityResult.citations || []
};

return [{
  json: {
    profil: profilText,
    guide: guideText,
    resultats_veille
  }
}];

const response = $input.first().json;
const text = response.candidates?.[0]?.content?.parts?.[0]?.text || '[]';

let propositions;
try {
  propositions = JSON.parse(text);
  if (!Array.isArray(propositions)) propositions = [propositions];
} catch(e) {
  return [];
}

const filtered = propositions.filter(p => (p.score || 0) >= 7);

return filtered.map(p => ({
  json: {
    date: new Date().toISOString().split('T')[0],
    sujet: p.sujet || '',
    angle: p.angle || '',
    plateforme: p.plateforme || 'LinkedIn',
    score: String(p.score || 0),
    priorite: p.priorite || 'Tendance',
    sources: p.sources || '',
    statut: 'PROPOSITION',
    notes: ''
  }
}));

const response = $input.first().json;
const text = response.candidates?.[0]?.content?.parts?.[0]?.text || '[]';

let propositions;
try {
  propositions = JSON.parse(text);
  if (!Array.isArray(propositions)) propositions = [propositions];
} catch(e) {
  return [{ json: { aucune_proposition: true, count: 0, message: 'Impossible de parser la reponse Gemini' } }];
}

const filtered = propositions.filter(p => (p.score || 0) >= 7);

if (filtered.length === 0) {
  return [{ json: { aucune_proposition: true, count: 0 } }];
}

return [];
